function validate([trees]) {
  if (!Array.isArray(trees) || trees.length < 1 || trees.length > 50000) return 'trees needs 1 to 5 * 10^4 trees.';
  const roots = new Set();
  for (const tree of trees) {
    if (!Array.isArray(tree) || tree.length < 1 || tree.length > 3 || tree[0] === null) return 'Each tree is [root], [root, left], [root, null, right] or [root, left, right].';
    const [root, left = null, right = null] = tree;
    for (const value of [root, left, right]) {
      if (value !== null && (!Number.isInteger(value) || value < 1 || value > 50000)) return 'Node values are whole numbers from 1 to 5 * 10^4.';
    }
    if (left !== null && left >= root) return 'A left child must be smaller than its root.';
    if (right !== null && right <= root) return 'A right child must be larger than its root.';
    if (roots.has(root)) return 'No two trees may have the same root value.';
    roots.add(root);
  }
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [trees] = input;
  const roots = trees.map(values => kit.toTree(values));
  const result = solve(roots);
  if (result === undefined) throw new Error('Return the root of the merged tree, or null.');
  return kit.fromTree(result);
}

