function canMerge(trees) {
  const rootOf = new Map();
  const leafValues = new Set();
  for (const tree of trees) {
    rootOf.set(tree.val, tree);
    if (tree.left) {
      leafValues.add(tree.left.val);
    }
    if (tree.right) {
      leafValues.add(tree.right.val);
    }
  }
  let top = null;
  for (const tree of trees) {
    if (!leafValues.has(tree.val)) {
      top = tree;
      break;
    }
  }
  if (top === null) {
    return null;
  }
  rootOf.delete(top.val);
  const grow = (node, low, high) => {
    if (node === null) {
      return true;
    }
    if (node.val <= low || node.val >= high) {
      return false;
    }
    const sub = rootOf.get(node.val);
    if (!node.left && !node.right && sub) {
      node.left = sub.left;
      node.right = sub.right;
      rootOf.delete(node.val);
    }
    return grow(node.left, low, node.val) && grow(node.right, node.val, high);
  };
  if (!grow(top, -Infinity, Infinity)) {
    return null;
  }
  return rootOf.size === 0 ? top : null;
}

