function canMerge(trees) {
  // Perform any available merge until none is left, then check the single survivor in order.
  const list = [...trees];
  const leafSlots = root => {
    const slots = [];
    const stack = [root];
    while (stack.length) {
      const node = stack.pop();
      for (const side of ['left', 'right']) {
        const child = node[side];
        if (!child) continue;
        if (!child.left && !child.right) slots.push([node, side]);
        else stack.push(child);
      }
    }
    return slots;
  };
  let merged = true;
  while (list.length > 1 && merged) {
    merged = false;
    for (let i = 0; i < list.length && !merged; i++) {
      for (const [parent, side] of leafSlots(list[i])) {
        const j = list.findIndex((tree, k) => k !== i && tree.val === parent[side].val);
        if (j >= 0) {
          parent[side] = list[j];
          list.splice(j, 1);
          merged = true;
          break;
        }
      }
    }
  }
  if (list.length !== 1) return null;
  const values = [];
  const inorder = node => {
    if (!node) return;
    inorder(node.left);
    values.push(node.val);
    inorder(node.right);
  };
  inorder(list[0]);
  for (let k = 1; k < values.length; k++) if (values[k] <= values[k - 1]) return null;
  return list[0];
}

