function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const limit = large || rand() < 0.4 ? 50000 : 30;
  const count = large ? 1500 + pick(400) : 1 + pick(Math.min(limit, 10));
  // Pick increasing values with random gaps, then shape one BST over them by choosing each subtree's root in its range.
  const gap = Math.max(1, Math.floor(limit / count));
  const values = [];
  for (let i = 0, v = pick(limit - count * gap + 1); i < count; i++) {
    v += 1 + pick(gap);
    values.push(v);
  }
  const shape = rand();
  const all = [];
  const stack = [[0, count - 1, null, null]];
  while (stack.length) {
    const [lo, hi, parent, side] = stack.pop();
    if (lo > hi) continue;
    // Mostly random splits; sometimes always the smallest (a long right chain) or a lopsided split.
    const m = shape < 0.1 ? lo : shape < 0.25 ? (rand() < 0.5 ? lo : hi) : lo + pick(hi - lo + 1);
    const node = { val: values[m], left: null, right: null };
    if (parent) parent[side] = node;
    all.push(node);
    stack.push([lo, m - 1, node, 'left'], [m + 1, hi, node, 'right']);
  }
  const root = all[0];
  // Cut the BST into pieces of height at most one: every node with children becomes a piece's root.
  const piece = node => {
    const out = [node.val, node.left ? node.left.val : null, node.right ? node.right.val : null];
    while (out.length > 1 && out[out.length - 1] === null) out.pop();
    return out;
  };
  let trees = all.filter(node => node === root || node.left || node.right).map(piece);
  const roots = new Set(trees.map(t => t[0]));
  // A leaf may also appear as a one-node tree of its own.
  for (const node of all) {
    if (trees.length >= 2000) break;
    if (!roots.has(node.val) && rand() < 0.1) { trees.push([node.val]); roots.add(node.val); }
  }
  const fresh = () => {
    let v = 1 + pick(limit);
    while (roots.has(v)) v = v % limit + 1;
    return v;
  };
  // Half of the inputs are disturbed so that the merge fails or yields a smaller tree.
  const changes = rand() < 0.5 ? 0 : 1 + pick(2);
  for (let c = 0; c < changes; c++) {
    const kind = pick(3);
    if (kind === 0) {
      // Change one child to another value that keeps its own piece a valid BST.
      const t = trees[pick(trees.length)];
      if (t[0] > 1 && rand() < 0.5) t[1] = Math.max(1, t[0] - 1 - pick(large ? 50 : 6));
      else if (t[0] < limit) { while (t.length < 2) t.push(null); t[2] = Math.min(limit, t[0] + 1 + pick(large ? 50 : 6)); }
    } else if (kind === 1 && trees.length > 1) {
      // Drop one piece.
      const i = pick(trees.length);
      roots.delete(trees[i][0]);
      trees.splice(i, 1);
    } else if (trees.length < 2000 && roots.size < limit) {
      // Add a piece with a new root and maybe some children.
      const v = fresh();
      const t = [v];
      if (v > 1 && rand() < 0.5) t.push(Math.max(1, v - 1 - pick(6)));
      if (v < limit && rand() < 0.5) { if (t.length < 2) t.push(null); t.push(Math.min(limit, v + 1 + pick(6))); }
      trees.push(t);
      roots.add(v);
    }
  }
  for (let i = trees.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [trees[i], trees[j]] = [trees[j], trees[i]];
  }
  return [trees];
}
